def first_cycle_rule(n, rules):
    def prefix_loops(k):
        after = [[] for _ in range(n)]
        waits = [0] * n
        for a, b in rules[:k]:
            after[a].append(b)
            waits[b] += 1
        ready = [j for j in range(n) if waits[j] == 0]
        done = 0
        while ready:
            j = ready.pop()
            done += 1
            for x in after[j]:
                waits[x] -= 1
                if waits[x] == 0:
                    ready.append(x)
        return done < n

    if not prefix_loops(len(rules)):
        return -1
    lo, hi = 1, len(rules)
    while lo < hi:
        mid = (lo + hi) // 2
        if prefix_loops(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo - 1

